def input_mapping(sender, keyword, date_range):
    # Expecting date_range as a string in the format 'start_date - end_date'
    parts = date_range.split('-')
    if len(parts) != 2:
        raise ValueError('date_range must be in the format "start_date - end_date"')
    start_date = parts[0].strip()
    end_date = parts[1].strip()
    return {
        'from': sender,
        'keywords': [keyword],
        'date_range': {'start_date': start_date, 'end_date': end_date}
    }

EmailSearch.output_mapping:
def output_mapping(result):
    emails = result.get('emails', [])
    if emails:
        # Assuming the most recent email is the one with the maximum timestamp value
        latest = max(emails, key=lambda email: email.get('timestamp', ''))
        # Construct a summary string with available details
        details = f"Subject: {latest.get('subject', '')}, Date: {latest.get('timestamp', '')}, From: {latest.get('from', '')}"
        return {'email_details': details}
    return {'email_details': ''}

